class Solution:
    def findPeakElement(self, nums):
        left = 0
        right = len(nums) - 1

        while left < right:
            mid = (left + right) // 2

            if nums[mid] < nums[mid + 1]:
                # Peak is on the right
                left = mid + 1
            else:
                # Peak is at mid or on the left
                right = mid

        return left
